flight_plan.header:
#include "autopilot.h"
#include "firmwares/fixedwing/guidance/energy_ctrl.h"
/* Quoted include, and NO angle brackets, ampersands or comparison operators
   anywhere in this header - not even inside a C comment, and not even
   correctly escaped. Xml-light (the OCaml parser the paparazzi generators
   use) fails outright on a raw angle bracket in element text: this file
   passed 'xmllint --valid' and still died with Xml_error until some arrows
   in these comments were reworded. Downstream, gen_aircraft does not
   re-escape header text on output, so even a properly escaped entity
   round-trips back out unescaped and corrupts the generated flight_plan.xml.
   So: signbit() on a subtraction does the comparisons, '!=' does the loop
   bounds, nested ifs replace logical and (a logical OR is spelled with two
   pipes and is safe; a logical AND needs the forbidden character, so it is
   written as nested ifs instead), and a 1-element array replaces taking an
   address. Inherited from mission4_strasbourg.xml. */
#include "stdio.h"
#include "stdlib.h"
#include "time.h"
#include "modules/datalink/datalink.h"
#include "modules/relative_localization_filter/relative_localization_filter.h"
#include "modules/core/abi.h"
#include "modules/nav/nav_mission4_geofence.h"

/* ===================================================================
   SITE MODEL. The sectors below are generated into InsideM4_* tests
   further down in the generated flight_plan.h, so they are forward
   declared here to be usable from this header's own functions.
   =================================================================== */
#ifndef FBW
static inline bool InsideM4_FENCE(float _x, float _y);

/* Valkenburg: no obstacle survey, so leaving the flyzone is the only thing
   the low run-in corridor is tested against. */
static bool m4_obstacle(float x, float y) __attribute__((unused));
static bool m4_obstacle(float x, float y)
{
  return !InsideM4_FENCE(x, y);
}
#endif

/* Run-in course, westbound at Valkenburg. From the placeholder
   SEARCH_CENTER a 300 m run-in from the south starts outside the flyzone;
   from the east it fits with ~90 m to spare and is usually into the
   prevailing westerly wind. The tilt search still tries +-20 deg about it,
   testing the corridor against the flyzone only (no obstacle sectors). */
#define M4_LANE_COURSE_DEG 270.f
#define M4_LANE_MAX_TILT_DEG 20.f
#define M4_LANE_TILT_STEP_DEG 2.f
#define M4_RUN_IN_M 300.f
#define M4_LANE_MARGIN_M 8.f
/* +1 = base turn and exit circle on the right of the run-in: north of a
   westbound run-in at Valkenburg. */
#define M4_DROPTURN_SIDE 1.f
/* Climb-out straight ahead past the target, then the exit circle. */
#define M4_CLIMBOUT_MAX_M 120.f
#define M4_CLIMBOUT_MIN_M 40.f
#define M4_CLIMBOUT_RATE_MPS 3.0f
#define M4_CLIMBOUT_AIRSPEED_MPS 11.f
#define M4_EXIT_TURN_RADIUS_M 30.f
/* The exit circle stays this far inside the geofence: turn-entry overshoot
   plus tailwind, GPS error and the fence's own accuracy. */
#define M4_FENCE_MARGIN_M 40.f
/* Above this height nothing at the site can be hit. The star flies here. */
#define M4_SAFE_HEIGHT_M 45.f
/* Below this height inside an obstacle sector = emergency climb. */
#define M4_ESCAPE_HEIGHT_M 25.f

/* ===================================================================
   Sonar AGL for the release gate. Unchanged from mission4_strasbourg.xml -
   see that file for why the gate cannot run on GPS/baro on real hardware,
   and why this subscribes to the Abi message directly.
   =================================================================== */
static float mission4_sonar_agl = -1.0f;
static float mission4_sonar_agl_time = -1000.0f;
static abi_event mission4_agl_ev[1];

static void mission4_agl_cb(uint8_t sender_id __attribute__((unused)),
                            uint32_t stamp __attribute__((unused)),
                            float distance)
{
  mission4_sonar_agl = distance;
  mission4_sonar_agl_time = autopilot.flight_time;
}

static inline void mission4_agl_sonar_init(void)
{
  AbiBindMsgAGL(AGL_RANGEFINDER_I2C_ID, mission4_agl_ev, mission4_agl_cb);
}

/* rangefinder_i2c is only loaded on the ap target; skip its report in NPS. */
static inline void mission4_rangefinder_report_start(void)
{
#ifdef RANGEFINDER_I2C_ADDR
  rangefinder_i2c_rangefinder_i2c_report_status = MODULES_START;
#endif
}

static inline float mission4_agl(void)
{
  if (!signbit(autopilot.flight_time - mission4_sonar_agl_time - 0.5f)) {
    return GetPosAlt() - GetAltRef();
  }
  return mission4_sonar_agl;
}

/* ===================================================================
   Release lead, drag, payload integration and logging. Unchanged from
   mission4_strasbourg.xml, which carries the measured numbers behind every
   term (the 13.3 m release that produced the formula, the drag and
   half-tick corrections).
   =================================================================== */
static float mission4_prev_d2 = 1.0e9f;

static inline bool mission4_closing(uint8_t drop_wp)
{
  float dx = GetPosX() - waypoints[drop_wp].x;
  float dy = GetPosY() - waypoints[drop_wp].y;
  float d2 = dx * dx + dy * dy;
  bool closing = signbit(d2 - mission4_prev_d2);
  mission4_prev_d2 = d2;
  return closing;
}

static inline float mission4_dist2_to_wp(uint8_t wp) {
  float dx = GetPosX() - waypoints[wp].x;
  float dy = GetPosY() - waypoints[wp].y;
  return dx * dx + dy * dy;
}

static inline float mission4_release_lead(void)
{
  float _v = stateGetHorizontalSpeedNorm_f();
  float _w = -(stateGetSpeedEnu_f()[0].z);
  if (signbit(_w)) { _w = 0.f; }

  float _h = mission4_agl() - _w * TRIGGER_DELAY;
  if (signbit(_h)) { _h = 0.f; }

  float _t = (-_w + sqrtf(_w * _w + 2.f * 9.81f * _h)) / 9.81f;

  float _dir = stateGetHorizontalSpeedDir_f();
  float _wn = stateGetHorizontalWindspeed_f()[0].x;
  float _we = stateGetHorizontalWindspeed_f()[0].y;
  float _walong = _we * sinf(_dir) + _wn * cosf(_dir);
  float _vrel = _v - _walong;

  float _throw = _v * _t;
  float _drag = 0.5f * ((float)ALPHA / (float)MASS) * _vrel * _vrel * _t * _t;
  if (!signbit(_drag - _throw)) { _drag = 0.f; }

  float _tick = _v / (2.0f * (float)NAVIGATION_FREQUENCY);

  return _v * TRIGGER_DELAY + (_throw - _drag) + _tick;
}

#ifdef SITL
static inline void mission4_sim_payload(uint8_t impact_wp)
{
  float dir = stateGetHorizontalSpeedDir_f();
  float v = stateGetHorizontalSpeedNorm_f();
  float x = GetPosX(), y = GetPosY(), z = mission4_agl();
  float vx = v * sinf(dir), vy = v * cosf(dir);
  float vz = stateGetSpeedEnu_f()[0].z;
  float we = stateGetHorizontalWindspeed_f()[0].y;
  float wn = stateGetHorizontalWindspeed_f()[0].x;
  float am = (float)ALPHA / (float)MASS;
  float dt = 0.005f;
  int k;

  int n = (int)(TRIGGER_DELAY / dt);
  for (k = 0; k != n; k++) { x += vx * dt; y += vy * dt; z += vz * dt; }

  for (k = 0; k != 4000; k++) {
    if (signbit(z)) { break; }
    float rx = vx - we, ry = vy - wn, rz = vz;
    float sp = sqrtf(rx * rx + ry * ry + rz * rz);
    float b = am * sp;
    vx -= rx * b * dt;
    vy -= ry * b * dt;
    vz -= rz * b * dt + 9.81f * dt;
    x += vx * dt; y += vy * dt; z += vz * dt;
  }
  waypoints[impact_wp].x = x;
  waypoints[impact_wp].y = y;
}
#endif

#ifndef SwitchServoOn
#define SwitchServoOn(_x) {}
#endif
#ifndef SwitchServoOff
#define SwitchServoOff(_x) {}
#endif
#define DropOpen SwitchServoOff
#define DropClose SwitchServoOn

/* ===================================================================
   Acoustic sampling and the multilateration solver. Unchanged from
   mission4_strasbourg.xml. Kept rather than replaced by their v2's
   "loudest spot": that is an argmax over AIRCRAFT positions, the rule
   mission4_strasbourg.xml measured at 2.3 m and abandoned.
   =================================================================== */
#define MISSION4_MAX_SAMPLES 600
#define MISSION4_SAMPLE_PERIOD 0.05f
#define MISSION4_KTR_REF_SPL 95.0f
#define MISSION4_KTR_REF_DIST 3.0f

static float mission4_sample_x[MISSION4_MAX_SAMPLES];
static float mission4_sample_y[MISSION4_MAX_SAMPLES];
static float mission4_sample_spl[MISSION4_MAX_SAMPLES];
static float mission4_sample_z[MISSION4_MAX_SAMPLES];
static uint16_t mission4_sample_count = 0;
static float mission4_last_sample_time = -1000.0f;
static float mission4_best_horiz = 1.0e6f;

/* ---- SPL MEASUREMENT NOISE -------------------------------------------
   The model above is an exact, noiseless inverse-square formula. That
   flatters every search pattern equally and makes them impossible to tell
   apart: geometry that suppresses error buys nothing when there is no
   error to suppress. Four flights comparing this file with
   mission4_strasbourg.xml produced miss distances that differed by less
   than the run-to-run scatter, for exactly that reason.

   Two terms, both of which a real single microphone has:

     WHITE, independent per sample - sensor, quantisation, ambient. It
     averages out as 1/sqrt(N) in the least-squares fit, so with hundreds
     of samples it is NOT what limits the answer.

     DRIFT, correlated over MISSION4_SPL_DRIFT_TAU seconds
     (Ornstein-Uhlenbeck): gusts on the diaphragm, source directivity as
     the aircraft's aspect changes, ground reflection changing with
     geometry. This one does NOT average away - samples taken close
     together in time share a bias, and the only defence is spatial and
     temporal diversity. It is the term that makes search GEOMETRY matter,
     and the reason a pattern crossing the target from several bearings
     should beat one that samples a single arc.

   1.5 dB each is not a small number here: at 45 m with a 10 m horizontal
   offset the slant range is 46 m, where 1 dB is about 5.3 m of range and,
   after removing the aircraft's own altitude, about 24 m of horizontal
   error in a SINGLE sample. That is what an uncalibrated mic against one
   beeper actually looks like, and it is why the solver needs many samples
   from many places rather than one good pass.

   Seeded from M4_NOISE_SEED when set, so a batch can hold everything else
   fixed and vary only the noise draw; otherwise from the clock. The same
   block is present verbatim in mission4_strasbourg.xml - if you change it
   here, change it there, or the comparison stops being a comparison. */
#define MISSION4_SPL_NOISE_DB 1.5f
#define MISSION4_SPL_DRIFT_DB 1.5f
#define MISSION4_SPL_DRIFT_TAU 5.0f

static uint32_t mission4_rng = 0u;
static float mission4_spl_drift = 0.0f;

static inline float mission4_rand_unit(void)
{
  mission4_rng = mission4_rng * 1664525u + 1013904223u;
  return (float)((mission4_rng / 65536u) % 32768u) / 32768.0f;
}

/* Irwin-Hall: twelve uniforms minus six is very close to N(0,1) and needs
   no log or sqrt, so it is cheap enough to run inside the sampling path. */
static inline float mission4_randn(void)
{
  float s = 0.0f;
  int i;
  for (i = 0; i != 12; i++) { s += mission4_rand_unit(); }
  return s - 6.0f;
}

static inline void mission4_noise_init(void)
{
  uint32_t seed = 1u;
#ifdef SITL
  const char *e = getenv("M4_NOISE_SEED");
  if (e != NULL) { seed = (uint32_t)atoi(e); }
  else { seed = (uint32_t)time(NULL); }
  printf("[M4NOISE] seed=%u white=%.2f dB drift=%.2f dB tau=%.1f s\n",
         (unsigned)seed, MISSION4_SPL_NOISE_DB, MISSION4_SPL_DRIFT_DB,
         MISSION4_SPL_DRIFT_TAU);
  fflush(stdout);
#endif
  mission4_rng = seed * 2654435761u + 1u;
  mission4_spl_drift = 0.0f;
}

static inline float mission4_spl_noise(void)
{
  float a = MISSION4_SAMPLE_PERIOD / MISSION4_SPL_DRIFT_TAU;
  mission4_spl_drift += -a * mission4_spl_drift
                      + sqrtf(2.0f * a) * MISSION4_SPL_DRIFT_DB * mission4_randn();
  return mission4_spl_drift + MISSION4_SPL_NOISE_DB * mission4_randn();
}

static inline bool mission4_solve_source(uint8_t drop_wp)
{
  if (signbit((float)mission4_sample_count - 8.0f)) { return FALSE; }

  double s11 = 0.0, s12 = 0.0, s13 = 0.0, s22 = 0.0, s23 = 0.0, s33 = 0.0;
  double t1 = 0.0, t2 = 0.0, t3 = 0.0;
  uint16_t i;
  uint16_t n = mission4_sample_count;

  for (i = 0; i != n; i++) {
    double zi = (double)mission4_sample_z[i];
    double slant = (double)MISSION4_KTR_REF_DIST *
                   pow(10.0, ((double)MISSION4_KTR_REF_SPL - (double)mission4_sample_spl[i]) / 20.0);
    double h2 = slant * slant - zi * zi;
    if (signbit((float)h2)) { continue; }
    double xi = (double)mission4_sample_x[i];
    double yi = (double)mission4_sample_y[i];
    double r  = xi * xi + yi * yi - h2;
    double a1 = 2.0 * xi, a2 = 2.0 * yi, a3 = -1.0;
    s11 += a1 * a1; s12 += a1 * a2; s13 += a1 * a3;
    s22 += a2 * a2; s23 += a2 * a3; s33 += a3 * a3;
    t1  += a1 * r;  t2  += a2 * r;  t3  += a3 * r;
  }

  double A11 = s22 * s33 - s23 * s23;
  double A12 = s13 * s23 - s12 * s33;
  double A13 = s12 * s23 - s13 * s22;
  double A22 = s11 * s33 - s13 * s13;
  double A23 = s13 * s12 - s11 * s23;
  double det = s11 * A11 + s12 * A12 + s13 * A13;
  if (signbit((float)(fabs(det) - 1.0e-3))) { return FALSE; }

  double X = (A11 * t1 + A12 * t2 + A13 * t3) / det;
  double Y = (A12 * t1 + A22 * t2 + A23 * t3) / det;

  waypoints[drop_wp].x = (float)X;
  waypoints[drop_wp].y = (float)Y;
  return TRUE;
}

static inline bool mission4_sample_signal(uint8_t source_wp, uint8_t drop_wp) {
  if (!signbit(autopilot.flight_time - mission4_last_sample_time - MISSION4_SAMPLE_PERIOD)) {
    mission4_last_sample_time = autopilot.flight_time;
    float dx = GetPosX() - waypoints[source_wp].x;
    float dy = GetPosY() - waypoints[source_wp].y;
    float dz = GetPosAlt() - GetAltRef();
    float dist = sqrtf(dx * dx + dy * dy + dz * dz);
    float spl = MISSION4_KTR_REF_SPL - 20.0f * log10f(dist / MISSION4_KTR_REF_DIST);
    /* Corrupt the reading BEFORE anything downstream sees it: the recorded
       sample, the best-so-far ranking and the solver must all work from the
       same noisy number a real microphone would have handed them. */
    spl += mission4_spl_noise();
    if (signbit((float)mission4_sample_count - (float)MISSION4_MAX_SAMPLES)) {
      mission4_sample_x[mission4_sample_count] = GetPosX();
      mission4_sample_y[mission4_sample_count] = GetPosY();
      mission4_sample_spl[mission4_sample_count] = spl;
      mission4_sample_z[mission4_sample_count] = GetPosAlt() - GetAltRef();
      mission4_sample_count++;
    }
    float own_alt = GetPosAlt() - GetAltRef();
    float slant = MISSION4_KTR_REF_DIST * powf(10.0f, (MISSION4_KTR_REF_SPL - spl) / 20.0f);
    float horiz2 = slant * slant - own_alt * own_alt;
    if (signbit(horiz2)) { horiz2 = 0.0f; }
    float horiz = sqrtf(horiz2);
    if (signbit(horiz - mission4_best_horiz)) {
      mission4_best_horiz = horiz;
      waypoints[drop_wp].x = GetPosX();
      waypoints[drop_wp].y = GetPosY();
    }
  }
  return false;
}

/* ===================================================================
   CLOVERLEAF STAR GEOMETRY

   N legs through the estimate at line-angle steps of D = 180/N, joined by
   turn circles of radius R tangent to both. Tangency FORCES the leg
   half-length L = R * cot(D/2): N=4 gives L = 2.414 R and 225 deg turns.
   Shorter legs and the turn cannot close, which is why L is derived and
   not configured.

   R = 25 m, their v2's value (they lowered it from 30 so the star fits the
   fence, and say not to enlarge it). NOTE this is below the EasyStar 3
   airframe's own declared MIN_CIRCLE_RADIUS of 30 m - about 22 deg of bank
   at 10 m/s rather than 19. Verified the 4-leg star at R=25 fits inside
   M4_FENCE from the search centre with no violations.

   The star is flown at M4_SAFE_HEIGHT_M, above every tree at the site, so
   its layout is tested against the FENCE ONLY. The low run-in is what has
   to clear the trees, and that is tested separately.
   =================================================================== */
#define MISSION4_STAR_R 25.0f
#define MISSION4_STAR_QUIET_BEFORE 40.0f
#define MISSION4_STAR_QUIET_AFTER  30.0f
#define MISSION4_STAR_SPINDOWN 1.5f
#define MISSION4_STAR_CONVERGE_M 1.5f
#define MISSION4_STAR_MAX_ITER 3
#define MISSION4_STAR_PLAUSIBLE_M 35.0f
#define MISSION4_STAR_ALIGN_RAD 0.175f
#define MISSION4_STAR_CRUISE_THR 0.16f
/* One airspeed across the quiet-window boundary: the setpoint slews at only
   0.3 m/s/s (AIRSPEED_SETPOINT_SLEW), so a step at the edge would still be
   settling well into the listening pass. Only the throttle changes. */
#define MISSION4_STAR_AIRSPEED 10.0f

static float mission4_star_cx, mission4_star_cy;
static float mission4_star_px, mission4_star_py;
static float mission4_star_L = 0.0f;
static uint8_t mission4_star_nlegs = 4;
static uint8_t mission4_star_leg = 0;
static uint8_t mission4_star_iter = 0;
static float mission4_star_shift_m = 9999.0f;
static bool mission4_star_converged = FALSE;
static bool mission4_star_quiet = FALSE;
static float mission4_star_quiet_t = -1000.0f;
static float mission4_star_s = 0.0f;

/* Line bearing of leg k. Left turns advance the pattern by -D each leg. */
static inline float mission4_star_phi(uint8_t k, uint8_t nlegs)
{
  return -(float)k * (3.14159265f / (float)nlegs);
}

/* Heading actually flown on leg k: even legs along +u, odd legs along -u,
   because that is what the 180+D degree left turn between them delivers. */
static inline float mission4_star_leg_heading(uint8_t k, uint8_t nlegs)
{
  float phi = mission4_star_phi(k, nlegs);
  if ((k % 2) != 0) { phi += 3.14159265f; }
  return phi;
}

/* Would an N-leg star centred here stay inside the fence? Tests both ends of
   every leg and twelve points around every turn loop - the loops reach
   furthest, sqrt(L^2+R^2)+R from the centre, so testing leg ends alone would
   pass a layout that busts. */
static inline bool mission4_star_fits(float cx, float cy, uint8_t nlegs)
{
  float dstep = 3.14159265f / (float)nlegs;
  float L = MISSION4_STAR_R / tanf(dstep * 0.5f);
  uint8_t k;
  for (k = 0; k != nlegs; k++) {
    float phi = mission4_star_phi(k, nlegs);
    float ux = sinf(phi), uy = cosf(phi);
    float ax = cx + ux * L, ay = cy + uy * L;
    float bx = cx - ux * L, by = cy - uy * L;
    if (!InsideM4_FENCE(ax, ay)) { return FALSE; }
    if (!InsideM4_FENCE(bx, by)) { return FALSE; }

    float ex, ey, hx, hy;
    if ((k % 2) == 0) { ex = ax; ey = ay; hx = ux; hy = uy; }
    else              { ex = bx; ey = by; hx = -ux; hy = -uy; }
    float tx = ex - hy * MISSION4_STAR_R;
    float ty = ey + hx * MISSION4_STAR_R;

    uint8_t s;
    for (s = 0; s != 12; s++) {
      float a = (float)s * (2.0f * 3.14159265f / 12.0f);
      if (!InsideM4_FENCE(tx + MISSION4_STAR_R * sinf(a),
                          ty + MISSION4_STAR_R * cosf(a))) { return FALSE; }
    }
  }
  return TRUE;
}

/* Place leg mission4_star_leg, and the turn circle that FOLLOWS it. */
static inline void mission4_star_place(uint8_t from_wp, uint8_t to_wp, uint8_t turn_wp, float height)
{
  float phi = mission4_star_phi(mission4_star_leg, mission4_star_nlegs);
  float ux = sinf(phi), uy = cosf(phi);
  float L = mission4_star_L;
  float ax, ay, bx, by;

  if ((mission4_star_leg % 2) == 0) {
    ax = mission4_star_cx - ux * L; ay = mission4_star_cy - uy * L;
    bx = mission4_star_cx + ux * L; by = mission4_star_cy + uy * L;
  } else {
    ax = mission4_star_cx + ux * L; ay = mission4_star_cy + uy * L;
    bx = mission4_star_cx - ux * L; by = mission4_star_cy - uy * L;
  }

  waypoints[from_wp].x = ax; waypoints[from_wp].y = ay;
  waypoints[to_wp].x   = bx; waypoints[to_wp].y   = by;

  /* Turn centre R to the LEFT of the exit heading: for a heading unit vector
     (hx,hy) in (east,north), left is (-hy,hx). */
  float hx = bx - ax, hy = by - ay;
  float hn = sqrtf(hx * hx + hy * hy);
  if (signbit(hn - 1.0f)) { hn = 1.0f; }
  hx /= hn; hy /= hn;
  waypoints[turn_wp].x = bx - hy * MISSION4_STAR_R;
  waypoints[turn_wp].y = by + hx * MISSION4_STAR_R;

  float a = GetAltRef() + height;
  waypoints[from_wp].a = a;
  waypoints[to_wp].a = a;
  waypoints[turn_wp].a = a;
}

static inline void mission4_star_begin(float cx, float cy, uint8_t from_wp, uint8_t to_wp,
                                       uint8_t turn_wp, float height)
{
  mission4_star_cx = cx;
  mission4_star_cy = cy;
  mission4_star_leg = 0;

  mission4_star_nlegs = 4;
  while (mission4_star_nlegs != 2) {
    if (mission4_star_fits(cx, cy, mission4_star_nlegs)) { break; }
    mission4_star_nlegs--;
  }

  mission4_star_L = MISSION4_STAR_R / tanf((3.14159265f / (float)mission4_star_nlegs) * 0.5f);
  mission4_star_place(from_wp, to_wp, turn_wp, height);
}

/* Advance AFTER the turn, matching their v2's leg-turn-next ordering.

   An earlier revision of this file reordered these to leg-next-turn, to skip
   the loop after the final leg. That desynchronised the turn point: place()
   writes the turn circle belonging to the leg it just placed, so the turn
   block then circled the NEXT leg's far-end turn, up to 145 m away. Two
   flights confirmed it - the aircraft flew away from the turn point every
   time and the joins became long ad-hoc transits. Their ordering was right. */
static inline uint8_t mission4_star_next_leg(uint8_t from_wp, uint8_t to_wp, uint8_t turn_wp, float height)
{
  mission4_star_leg++;
  if (mission4_star_leg != mission4_star_nlegs) {
    mission4_star_place(from_wp, to_wp, turn_wp, height);
    return 0;
  }
  return 1;
}

/* True while the aircraft is not yet lined up with the NEXT leg. Computed
   from the leg index, not from the waypoints, because the next leg has not
   been placed yet at this point in the sequence. Returns false when there is
   no next leg, so the turn block falls straight through after the last one
   instead of flying a wasted 225 deg loop. */
static inline bool mission4_star_turning(void)
{
  uint8_t k = mission4_star_leg + 1;
  if (k == mission4_star_nlegs) { return FALSE; }
  float want = mission4_star_leg_heading(k, mission4_star_nlegs);
  float d = want - stateGetHorizontalSpeedDir_f();
  while (!signbit(d - 3.14159265f)) { d -= 2.0f * 3.14159265f; }
  while (signbit(d + 3.14159265f)) { d += 2.0f * 3.14159265f; }
  if (signbit(fabs(d) - MISSION4_STAR_ALIGN_RAD)) { return FALSE; }
  return TRUE;
}

/* Left turns, so a negative (counter-clockwise) circle radius: nav_circle_XY
   accumulates progress for trigo_diff * -sign_radius, and a left turn
   increases the trigonometric angle. */
static inline float mission4_star_turn_radius(void)
{
  return -MISSION4_STAR_R;
}

/* Every cycle on a leg: cut power in the window around the estimate, restore
   it outside, and record the along-track position for the altitude command.

   Zeroing the nominal cruise throttle rather than setting
   autopilot.kill_throttle is not stylistic: kill_throttle is ANDed into
   nps_autopilot.launch (nps_autopilot_fixedwing.c), which gates
   nps_fdm_run_step, so killing the throttle FREEZES the simulator. Their
   design cuts the motor exactly that way and is untestable in SITL as
   written. */
static inline void mission4_star_leg_throttle(uint8_t from_wp, uint8_t to_wp)
{
  float hx = waypoints[to_wp].x - waypoints[from_wp].x;
  float hy = waypoints[to_wp].y - waypoints[from_wp].y;
  float hn = sqrtf(hx * hx + hy * hy);
  if (signbit(hn - 1.0f)) { return; }
  hx /= hn; hy /= hn;

  mission4_star_s = (GetPosX() - mission4_star_cx) * hx
                  + (GetPosY() - mission4_star_cy) * hy;

  bool quiet = TRUE;
  if (signbit(mission4_star_s + MISSION4_STAR_QUIET_BEFORE)) { quiet = FALSE; }
  if (!signbit(mission4_star_s - MISSION4_STAR_QUIET_AFTER)) { quiet = FALSE; }

  v_ctl_auto_airspeed_setpoint = MISSION4_STAR_AIRSPEED;
  if (quiet) {
    if (!mission4_star_quiet) { mission4_star_quiet_t = autopilot.flight_time; }
    v_ctl_auto_throttle_nominal_cruise_throttle = 0.f;
  } else {
    v_ctl_auto_throttle_nominal_cruise_throttle = MISSION4_STAR_CRUISE_THR;
  }
  mission4_star_quiet = quiet;
}

/* Sample only while genuinely quiet AND past the prop spin-down - their
   earcam_quiet_only. It is what lets the star run the motor at all: samples
   taken under power are worthless to a microphone beside a pusher prop. */
static inline bool mission4_star_sample(uint8_t src_wp, uint8_t drop_wp)
{
  if (!mission4_star_quiet) { return FALSE; }
  if (signbit(autopilot.flight_time - mission4_star_quiet_t - MISSION4_STAR_SPINDOWN)) { return FALSE; }
  return mission4_sample_signal(src_wp, drop_wp);
}

/* Level at the search height outside the quiet window, and the natural glide
   inside it - the motor is off there, so commanding level flight would only
   make the altitude loop fight an engine that is not running. From 45 m the
   70 m window sheds about 6.4 m at this airframe's 11:1 glide, leaving well
   over 20 m above the tallest tree. */
static inline float mission4_star_leg_alt(float height, float floor_m)
{
  if (!mission4_star_quiet) { return GetAltRef() + height; }
  float run = mission4_star_s + MISSION4_STAR_QUIET_BEFORE;
  if (signbit(run)) { run = 0.f; }
  /* V_CTL_GLIDE_RATIO, not GLIDE_RATIO: the airframe declares it inside the
     vertical control section, so the generated airframe.h prefixes it. */
  float h = height - run / (float)V_CTL_GLIDE_RATIO;
  if (signbit(h - floor_m)) { h = floor_m; }
  return GetAltRef() + h;
}

static inline void mission4_star_update(uint8_t est_wp)
{
  float nx = waypoints[est_wp].x, ny = waypoints[est_wp].y;
  float dx = nx - mission4_star_px, dy = ny - mission4_star_py;
  mission4_star_shift_m = sqrtf(dx * dx + dy * dy);
  mission4_star_px = nx;
  mission4_star_py = ny;
  mission4_star_iter++;

  mission4_star_converged = FALSE;
  if (signbit(mission4_star_shift_m - MISSION4_STAR_CONVERGE_M)) { mission4_star_converged = TRUE; }
  if (!signbit((float)mission4_star_iter - (float)MISSION4_STAR_MAX_ITER)) { mission4_star_converged = TRUE; }
}

/* The rules put the alarm within 25 m of the given point, so an estimate
   further out is another source - a generator, another team's aircraft - and
   must not be flown to. mission4_strasbourg.xml has no equivalent gate. */
static inline bool mission4_star_plausible(uint8_t est_wp, uint8_t ref_wp)
{
  float dx = waypoints[est_wp].x - waypoints[ref_wp].x;
  float dy = waypoints[est_wp].y - waypoints[ref_wp].y;
  if (signbit(dx * dx + dy * dy - MISSION4_STAR_PLAUSIBLE_M * MISSION4_STAR_PLAUSIBLE_M)) { return TRUE; }
  return FALSE;
}

static inline void mission4_star_reset(uint8_t ref_wp)
{
  mission4_sample_count = 0;
  mission4_best_horiz = 1.0e6f;
  mission4_star_iter = 0;
  mission4_star_shift_m = 9999.0f;
  mission4_star_converged = FALSE;
  mission4_star_quiet = FALSE;
  mission4_star_px = waypoints[ref_wp].x;
  mission4_star_py = waypoints[ref_wp].y;
}

/* ===================================================================
   OBSTACLE-AWARE RUN-IN, from their v2.
   =================================================================== */
static bool mission4_run_in_clear = FALSE;
static float mission4_run_in_ux = 0.0f;
static float mission4_run_in_uy = 1.0f;

/* Is a corridor of half width `half` clear of trees and inside the fence,
   from `back` metres before the target to `fwd` metres past it? Samples the
   centreline and both edges - testing the centreline alone would let a wing
   clip a crown the track itself misses. */
static inline bool mission4_corridor_clear(float cx, float cy, float ux, float uy,
                                           float back, float fwd, float half)
{
  int i;
  for (i = 0; i != 121; i++) {
    float s = -back + (back + fwd) * (float)i / 120.0f;
    float px = cx + ux * s, py = cy + uy * s;
    if (m4_obstacle(px, py)) { return FALSE; }
    if (m4_obstacle(px - uy * half, py + ux * half)) { return FALSE; }
    if (m4_obstacle(px + uy * half, py - ux * half)) { return FALSE; }
  }
  return TRUE;
}

/* Place START on the lane. Tries the lane course first, then alternating
   tilts either side up to the maximum, and takes the first whose whole
   corridor is clear. Sets mission4_run_in_clear; if nothing is clear the
   caller must NOT drop - a release above 2 m scores nothing, so there is no
   version of "try anyway" that is worth the risk.

   Their v2 breaks ties towards the wind. Nothing onboard estimates wind on
   this airframe - air_data only ever gets wind from an uplinked WIND_INFO -
   so this takes the smallest tilt instead, i.e. the straightest run down the
   lane. Restore the wind preference when there is a wind estimate to use. */
static inline void mission4_place_run_in_lane(uint8_t drop_wp, uint8_t start_wp)
{
  float sx = waypoints[drop_wp].x, sy = waypoints[drop_wp].y;
  float base = M4_LANE_COURSE_DEG * (3.14159265f / 180.0f);
  float step = M4_LANE_TILT_STEP_DEG * (3.14159265f / 180.0f);
  int n = (int)(M4_LANE_MAX_TILT_DEG / M4_LANE_TILT_STEP_DEG);
  int i;

  mission4_run_in_clear = FALSE;
  for (i = 0; i != 2 * n + 1; i++) {
    int half = (i + 1) / 2;
    float sgn = ((i % 2) == 0) ? 1.0f : -1.0f;
    float b = base + sgn * (float)half * step;
    float ux = sinf(b), uy = cosf(b);
    if (mission4_corridor_clear(sx, sy, ux, uy, M4_RUN_IN_M, M4_CLIMBOUT_MAX_M, M4_LANE_MARGIN_M)) {
      mission4_run_in_ux = ux;
      mission4_run_in_uy = uy;
      waypoints[start_wp].x = sx - ux * M4_RUN_IN_M;
      waypoints[start_wp].y = sy - uy * M4_RUN_IN_M;
      mission4_run_in_clear = TRUE;
      return;
    }
  }
}

/* Base turn circle centre, M4_DROPTURN_SIDE of the run-in beside START.
   Right of a heading (ux,uy) is (uy,-ux). */
static inline void mission4_place_dropturn(uint8_t start_wp, uint8_t turn_wp, float radius)
{
  float r = fabs(radius) * M4_DROPTURN_SIDE;
  waypoints[turn_wp].x = waypoints[start_wp].x + mission4_run_in_uy * r;
  waypoints[turn_wp].y = waypoints[start_wp].y - mission4_run_in_ux * r;
  waypoints[turn_wp].a = waypoints[start_wp].a;
}

static inline bool mission4_circle_in_fence(float cx, float cy, float r)
{
  uint8_t i;
  for (i = 0; i != 16; i++) {
    float a = (float)i * (2.0f * 3.14159265f / 16.0f);
    if (!InsideM4_FENCE(cx + r * sinf(a), cy + r * cosf(a))) { return FALSE; }
  }
  return TRUE;
}

/* Climb-out straight ahead on the run-in course, as far as
   M4_CLIMBOUT_MAX_M but stopping where a full exit turn plus fence margin
   would leave the geofence. Their v2 exists because the fence's north edge
   is only ~142 m past the target, and because the nav_drop default climb-out
   turns towards the east trees while still low. */
static inline void mission4_place_climbout(uint8_t drop_wp, uint8_t climbout_wp,
                                           uint8_t exit_wp, float height)
{
  float sx = waypoints[drop_wp].x, sy = waypoints[drop_wp].y;
  float ux = mission4_run_in_ux, uy = mission4_run_in_uy;
  float d = M4_CLIMBOUT_MAX_M;

  while (!signbit(d - M4_CLIMBOUT_MIN_M)) {
    float cx = sx + ux * d, cy = sy + uy * d;
    float ex = cx + uy * M4_EXIT_TURN_RADIUS_M * M4_DROPTURN_SIDE;
    float ey = cy - ux * M4_EXIT_TURN_RADIUS_M * M4_DROPTURN_SIDE;
    if (mission4_circle_in_fence(ex, ey, M4_EXIT_TURN_RADIUS_M + M4_FENCE_MARGIN_M)) {
      waypoints[climbout_wp].x = cx;
      waypoints[climbout_wp].y = cy;
      waypoints[climbout_wp].a = GetAltRef() + height - 10.0f;
      waypoints[exit_wp].x = ex;
      waypoints[exit_wp].y = ey;
      waypoints[exit_wp].a = GetAltRef() + height;
      return;
    }
    d -= 10.0f;
  }

  /* Fence too tight even at the minimum: climb straight ahead and put the
     exit circle on the climb-out point itself, so the aircraft spirals up
     where it is rather than turning towards anything. */
  waypoints[climbout_wp].x = sx + ux * M4_CLIMBOUT_MIN_M;
  waypoints[climbout_wp].y = sy + uy * M4_CLIMBOUT_MIN_M;
  waypoints[climbout_wp].a = GetAltRef() + height - 10.0f;
  waypoints[exit_wp].x = waypoints[climbout_wp].x;
  waypoints[exit_wp].y = waypoints[climbout_wp].y;
  waypoints[exit_wp].a = GetAltRef() + height;
}

/* Level-off point, `d` metres before the target on the run-in course. */
static inline void mission4_place_level(uint8_t drop_wp, uint8_t level_wp, float d, float height)
{
  waypoints[level_wp].x = waypoints[drop_wp].x - mission4_run_in_ux * d;
  waypoints[level_wp].y = waypoints[drop_wp].y - mission4_run_in_uy * d;
  waypoints[level_wp].a = GetAltRef() + height;
}

/* Release conditions at the instant the gate fires, plus the search and
   corridor diagnostics this file exists to collect. */
static inline void mission4_log_release(uint8_t drop_wp, uint8_t true_wp, uint8_t impact_wp)
{
  char _m4msg[128];
  float _agl_gate = mission4_agl();
  float _spd = stateGetHorizontalSpeedNorm_f();
  float _lead = mission4_release_lead();
  float _px = GetPosX(), _py = GetPosY();
  float _tx = _px - waypoints[true_wp].x, _ty = _py - waypoints[true_wp].y;
  float _d_true = sqrtf(_tx * _tx + _ty * _ty);
  float _dir = stateGetHorizontalSpeedDir_f();
  float _ix = _px + _lead * sinf(_dir), _iy = _py + _lead * cosf(_dir);
  float _mx = _ix - waypoints[true_wp].x, _my = _iy - waypoints[true_wp].y;
  float _miss = sqrtf(_mx * _mx + _my * _my);
  waypoints[impact_wp].x = _ix;
  waypoints[impact_wp].y = _iy;
  waypoints[impact_wp].a = waypoints[true_wp].a;
  float _sim = -1.0f;
#ifdef SITL
  mission4_sim_payload(impact_wp);
  float _sx = waypoints[impact_wp].x - waypoints[true_wp].x;
  float _sy = waypoints[impact_wp].y - waypoints[true_wp].y;
  _sim = sqrtf(_sx * _sx + _sy * _sy);
#endif
  float _tilt = DegOfRad(atan2f(mission4_run_in_ux, mission4_run_in_uy));
  int _n = snprintf(_m4msg, sizeof(_m4msg),
                    "STARDROP agl=%.2f dTrue=%.1f MISS=%.2f SIM=%.2f n=%u it=%u sh=%.1f lane=%.0f",
                    _agl_gate, _d_true, _miss, _sim,
                    (unsigned)mission4_star_nlegs, (unsigned)mission4_star_iter,
                    mission4_star_shift_m, _tilt);
  if (!signbit((float)_n)) {
    DOWNLINK_SEND_INFO_MSG(DefaultChannel, DefaultDevice, (uint8_t)_n, _m4msg);
  }
#ifdef SITL
  printf("[M4STAR] release: AGL %.2f m, %.1f m/s, lead %.1f m, %.1f m from TRUE source\n"
         "         predicted MISS %.2f m, integrated %.2f m\n"
         "         search: %u legs/star, %u stars, final shift %.2f m, lane course %.0f deg\n",
         _agl_gate, _spd, _lead, _d_true, _miss, _sim,
         (unsigned)mission4_star_nlegs, (unsigned)mission4_star_iter,
         mission4_star_shift_m, _tilt);
  fflush(stdout);
#endif
}

static inline float mission1_geo_init_delay(void) { return 5; }
static inline float mission1_holding_delay(void) { return 5; }
